SELECT EXISTS (
    SELECT 1 FROM application
    WHERE business_id = #{businessId}
    AND fair_id = #{fairId}
    AND status IN ('PENDING_REVIEW', 'PAYMENT_PENDING', 'CONFIRMED')
)

SELECT aps.booth_slot_id FROM application_slot aps JOIN application a ON a.application_id = aps.application_id WHERE aps.booth_slot_id IN
#{id}
AND a.status IN ('PENDING_REVIEW', 'PAYMENT_PENDING', 'CONFIRMED')

SELECT a.application_id AS applicationId, f.name AS fairName, a.status AS status, a.final_price AS finalPrice, a.reject_reason AS rejectReason, acr.status AS cancelRequestStatus FROM application a JOIN business b ON b.business_id = a.business_id JOIN fairs f ON f.fair_id = a.fair_id LEFT JOIN application_cancel_request acr ON acr.application_id = a.application_id AND acr.cancel_request_id = ( SELECT MAX(cancel_request_id) FROM application_cancel_request WHERE application_id = a.application_id ) WHERE b.owner_id = #{ownerId}
AND a.business_id = #{businessId}
ORDER BY a.submitted_at DESC

SELECT a.application_id AS applicationId, a.business_id AS businessId, b.name AS businessName, a.status AS status, a.submitted_at AS submittedAt, a.final_price AS finalPrice, a.reject_reason AS rejectReason FROM application a JOIN business b ON b.business_id = a.business_id WHERE a.fair_id = #{fairId}
AND a.status = #{status}
ORDER BY a.submitted_at DESC

SELECT COALESCE(SUM(price_at_selection), 0)
FROM application_slot
WHERE application_id = #{applicationId}

