UPDATE application
SET status = 'REJECTED',
    reject_reason = #{rejectReason},
    reviewed_at = #{reviewedAt}
WHERE application_id = #{applicationId}
AND status = 'PENDING_REVIEW'

mapper.select:
SELECT acr.cancel_request_id AS cancelRequestId, acr.application_id AS applicationId, a.business_id AS businessId, b.name AS businessName, acr.reason AS reason, acr.status AS status, acr.requested_at AS requestedAt, acr.decided_at AS decidedAt FROM application_cancel_request acr JOIN application a ON a.application_id = acr.application_id JOIN business b ON b.business_id = a.business_id WHERE a.fair_id = #{fairId}
AND acr.status = #{status}
ORDER BY acr.requested_at DESC

mapper.update:
UPDATE application_cancel_request
SET status = 'APPROVED', decided_at = #{decidedAt}
WHERE cancel_request_id = #{cancelRequestId} AND status = 'REQUESTED'

UPDATE application_cancel_request
SET status = 'REJECTED', decided_at = #{decidedAt}
WHERE cancel_request_id = #{cancelRequestId} AND status = 'REQUESTED'
